import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CNDaxUod.js";const c=JSON.parse('{"title":"3. Guided setup and first test","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-standup.md","filePath":"guide/first-standup.md"}'),n={name:"guide/first-standup.md"};function r(i,e,d,p,h,l){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-guided-setup-and-first-test" tabindex="-1">3. Guided setup and first test <a class="header-anchor" href="#_3-guided-setup-and-first-test" aria-label="Permalink to &quot;3. Guided setup and first test&quot;">​</a></h1><p>Step 3 of the <a href="./getting-started.html">setup path</a>. Finish the guided setup, then run a standup where only you can see it, before anyone else is prompted.</p><h2 id="finish-the-guided-setup" tabindex="-1">Finish the guided setup <a class="header-anchor" href="#finish-the-guided-setup" aria-label="Permalink to &quot;Finish the guided setup&quot;">​</a></h2><p>Open <code>https://HOST/app</code> and sign in with the operator token. A fresh install opens the guided setup at <code>/app/setup</code>. Progress is saved as you go, and you can come back to it any time.</p><table tabindex="0"><thead><tr><th>Step</th><th>What it checks</th></tr></thead><tbody><tr><td>Create a Google Cloud project</td><td>The project number has the right format</td></tr><tr><td>Service account</td><td>The key mints a token and lists the spaces the app is in</td></tr><tr><td>Configure the Chat app</td><td>A signed event from Google Chat arrived</td></tr><tr><td>Sign-in for your team <em>(optional)</em></td><td>Google or SAML sign-in; see <a href="./enterprise-sso.html">step 6</a>. Skip it for now if you like: the operator token keeps working</td></tr><tr><td>Create your first standup</td><td>Template, space, people, schedule</td></tr></tbody></table><p>Steps 1 to 3 are described in <a href="./google-chat-setup.html">step 2</a>. The rest of this page covers the last one. <strong>Before you reach it, make the private test space below</strong>, so it&#39;s there to pick.</p><h2 id="make-a-private-test-space" tabindex="-1">Make a private test space <a class="header-anchor" href="#make-a-private-test-space" aria-label="Permalink to &quot;Make a private test space&quot;">​</a></h2><ol><li>In Google Chat, create a new space, e.g. <em>AsyncUp test</em>, with only yourself in it.</li><li>Add the app: open the space, <strong>+ Add people &amp; apps</strong>, pick <strong>AsyncUp</strong>.</li></ol><p>Nobody else sees a thing until you create a standup in a real team space.</p><h2 id="create-a-test-standup" tabindex="-1">Create a test standup <a class="header-anchor" href="#create-a-test-standup" aria-label="Permalink to &quot;Create a test standup&quot;">​</a></h2><p>In the guided setup (or later from <strong>Standups → New standup</strong>):</p><ol><li>Pick a template. <strong>Daily standup</strong> is the usual one.</li><li><strong>Name</strong>: something like <em>Test standup</em>. Names are unique across the workspace, archived standups included; the form warns before you press Create if the name is taken.</li><li><strong>Post in space</strong>: your test space.</li><li><strong>Who is on it</strong>: <em>People I pick from the space</em>. You are the only member, so you&#39;re ticked.</li><li><strong>Schedule</strong>: set <strong>Deadline</strong> later than the current time. Prompt and deadline are time pickers; the deadline is in the standup&#39;s timezone.</li><li>Press <strong>Create and run it now</strong>.</li></ol><p><code>run now</code> (also the <strong>Run now</strong> button on a standup&#39;s Overview, and the <code>@AsyncUp run now</code> command) is refused once today&#39;s deadline has passed, because the run would close as soon as it opened. Move the deadline and try again. A scheduled run never opens after its deadline either.</p><h2 id="walk-through-a-run" tabindex="-1">Walk through a run <a class="header-anchor" href="#walk-through-a-run" aria-label="Permalink to &quot;Walk through a run&quot;">​</a></h2><p>You get a DM card from AsyncUp.</p><ol><li><strong>Skip first, to see it work.</strong> Press <strong>Skip today</strong>. A one-line dialog asks why. The reason appears as a reply in today&#39;s thread in the test space, and your card changes to <em>You skipped today</em> with <strong>Undo skip</strong>.</li><li><strong>Undo it.</strong> Press <strong>Undo skip</strong> (or DM the bot <code>unskip</code>). The thread reply disappears and the card offers <strong>Fill standup</strong> again.</li><li><strong>Answer.</strong> Press <strong>Fill standup</strong>. Every question and the mood are required; answer the blockers question with &quot;none&quot; if you have none. Submit, and your answers post as a card under today&#39;s thread.</li><li><strong>Edit.</strong> Your DM card now says <em>Submitted at …</em> with <strong>Edit answers</strong> until the deadline. Editing updates the posted card in place, marked <em>edited</em>.</li><li><strong>Try a blocker</strong> (optional). Answer the blockers question with anything other than &quot;none&quot;. The bot DMs you a blocker card with <strong>Tag people</strong>, so you can pull in whoever can help.</li><li><strong>Wait for the deadline.</strong> The wrap-up posts in the thread: how many answered, and who didn&#39;t.</li></ol><p>The web app&#39;s standup <strong>Overview</strong> shows the same run live: who submitted, who is still expected, and who is away and why.</p><h2 id="clean-up" tabindex="-1">Clean up <a class="header-anchor" href="#clean-up" aria-label="Permalink to &quot;Clean up&quot;">​</a></h2><p>When you&#39;re done, remove the test standup:</p><ol><li>Open it, <strong>Settings → Danger zone → Archive standup</strong>, type <code>ARCHIVE</code>.</li><li>Then <strong>Delete standup</strong>, and type the standup&#39;s name. This removes every run, answer, blocker and poll for good, and frees the name. Only workspace admins (and the operator token) can delete, and only an archived standup.</li></ol><p>Messages already posted in Chat stay; delete the test space itself if you like.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./distribution.html">Step 4: roll out to your team</a>, then create the real standup in your team&#39;s space, either here or with <code>@AsyncUp setup &lt;name&gt;</code> in Chat.</p>',23)])])}const g=t(n,[["render",r]]);export{c as __pageData,g as default};
